-- CA_0152_la_trustee_area_boards_batch6.sql
-- LA-County TRUSTEE-AREA unified school boards, batch 6: Paramount, Montebello, Acton-Agua Dulce.
-- These three are MID-TRANSITION from at-large to by-trustee-area elections: most sitting members were
-- elected AT LARGE and represent the whole district until their terms end; several trustee areas are
-- first filled by the Nov 3 2026 election. Modeled per the decision of 2026-09-22 (user, for Montebello;
-- applied to the two districts in the same position):
--   * AT-LARGE HOLDOVERS stay on the whole-district SCHOOL row (TIGER G5420), one office each, titled
--     'Board Member (At-Large)', so every address in the district sees them;
--   * each trustee area with a sitting AREA member gets its own X0002 sub-district + office (Paramount
--     TA 2 and TA 3; Acton-Agua Dulce TA 4, appointed 2026-06-30 to that area's seat);
--   * each trustee area FIRST FILLED by the Nov 2026 election gets a NEW office flagged vacant
--     (vacant_since NULL) to carry its race (Paramount TA 1, 4, 5; Montebello TA 1-3; Acton TA 1, 2);
--   * areas first elected in 2028 are not created yet (Montebello TA 4-5; Acton TA 3, 5), so those two
--     districts are PARTIAL partitions and their coverage tolerance is 1.0 -- the "no area outside
--     TIGER" check still applies.
-- Polygons: LA RR/CC precinct layer, DST_USD codes 14 Paramount, 50 Montebello, 58 Acton-Agua Dulce.
-- Rosters: each district's board page + organizational-meeting minutes (Acton: Diligent/HighBond
-- meeting records, because its board page still lists Lester Mascon). Stale DB holders closed as in
-- earlier batches; surplus offices deleted, missing ones cloned.
-- Incumbent candidates are linked to the holdover or area member they are. Jessica Gonyea (Acton TA 4)
-- is marked incumbent although the Registrar's filing-time list predates her appointment.
BEGIN;

CREATE TEMP TABLE _seat (parent_geo text, geo_id text, label text, ta text, ord int, full_name text, first_name text,
                         last_name text, url text, existing_pid uuid, term_start date, prec text, how text, src text,
                         pin_office uuid, vacant_since date, fresh boolean, pid uuid) ON COMMIT DROP;
CREATE TEMP TABLE _hold (parent_geo text, ord int, full_name text, first_name text, last_name text, url text,
                         existing_pid uuid, term_start date, prec text, how text, src text, pid uuid) ON COMMIT DROP;
