,[-118.219694,34.465715],[-118.219689,34.464681]]]}')
  ) AS v(geo_id, name, gj)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.geofence_boundaries b WHERE b.geo_id = v.geo_id AND b.mtfcc = 'X0002');

-- ─── 2. One SCHOOL sub-district per trustee area (X0002: the layer the Part A join admits) ─
INSERT INTO essentials.districts (label, district_type, district_id, state, num_officials, mtfcc, geo_id,
                                  is_judicial, has_unknown_boundaries, retention, representation_basis)
SELECT s.label, 'SCHOOL', s.geo_id, 'CA', 1, 'X0002', s.geo_id, false, false, false, 'residency'
  FROM _seat s
 WHERE NOT EXISTS (SELECT 1 FROM essentials.districts d WHERE d.geo_id = s.geo_id AND d.district_type = 'SCHOOL');

-- ─── 3. Move the generic 'Board Member' offices onto the areas ────────────────────────────
-- They carry only STALE holders, so the office-to-area pairing is arbitrary; take id order
-- (deterministic). Guarded on the office still sitting on the whole-district row.
-- An office already held by a verified CURRENT member is pinned to that member's area.
UPDATE essentials.offices o
   SET district_id = sd.id, title = 'Board Member (Trustee Area ' || s.ta || ')'
  FROM _seat s
  JOIN essentials.districts pd ON pd.geo_id = s.parent_geo AND pd.district_type = 'SCHOOL' AND pd.mtfcc = 'G5420'
  JOIN essentials.districts sd ON sd.geo_id = s.geo_id AND sd.district_type = 'SCHOOL'
 WHERE s.pin_office IS NOT NULL AND o.id = s.pin_office AND o.district_id = pd.id;
UPDATE essentials.offices o
   SET district_id = sd.id, title = 'Board Member (Trustee Area ' || s.ta || ')'
  FROM (SELECT o2.id, pd.geo_id AS parent_geo, row_number() OVER (PARTITION BY pd.geo_id ORDER BY o2.id) AS ord
          FROM essentials.offices o2 JOIN essentials.districts pd ON pd.id = o2.district_id
         WHERE pd.district_type = 'SCHOOL' AND pd.mtfcc = 'G5420' AND pd.geo_id IN ('0629850', '0625470', '0600001')) cur
  JOIN (SELECT s2.*, row_number() OVER (PARTITION BY s2.parent_geo ORDER BY s2.ord)
               + (SELECT count(*) FROM _hold h WHERE h.parent_geo = s2.parent_geo) AS free_ord
          FROM _seat s2
         WHERE s2.pin_office IS NULL AND NOT s2.fresh
           AND NOT EXISTS (SELECT 1 FROM essentials.offices ox JOIN essentials.districts dx ON dx.id = ox.district_id
                            WHERE dx.geo_id = s2.geo_id AND dx.district_type = 'SCHOOL')) s
    ON s.parent_geo = cur.parent_geo AND s.free_ord = cur.ord
  JOIN essentials.districts sd ON sd.geo_id = s.geo_id AND sd.district_type = 'SCHOOL'
 WHERE o.id = cur.id;

-- ─── 3b. MISSING seats (the DB had fewer offices than the board has areas): clone one ─────
-- (decision 2026-09-22: add missing seats, cloning chamber/title from an existing office)
INSERT INTO essentials.offices (chamber_id, district_id, title, representing_state, representing_city, seats,
                                normalized_position_name, partisan_type, is_appointed_position, is_vacant, role_canonical)
SELECT tpl.chamber_id, sd.id, 'Board Member (Trustee Area ' || s.ta || ')', tpl.representing_state, tpl.representing_city, 1,
       tpl.normalized_position_name, tpl.partisan_type, false, false, tpl.role_canonical
  FROM _seat s
  JOIN essentials.districts sd ON sd.geo_id = s.geo_id AND sd.district_type = 'SCHOOL'
  CROSS JOIN LATERAL (SELECT o.* FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
                       WHERE d.district_type = 'SCHOOL'
                         AND (d.geo_id IN (SELECT s2.geo_id FROM _seat s2 WHERE s2.parent_geo = s.parent_geo)
                              OR (d.geo_id = s.parent_geo AND d.mtfcc = 'G5420'))
                       ORDER BY (d.geo_id = s.parent_geo), o.id LIMIT 1) tpl
 WHERE NOT EXISTS (SELECT 1 FROM essentials.offices ox WHERE ox.district_id = sd.id);

-- Parent row short of offices for its at-large holdovers: clone the missing ones there.
INSERT INTO essentials.offices (chamber_id, district_id, title, representing_state, representing_city, seats,
                                normalized_position_name, partisan_type, is_appointed_position, is_vacant, role_canonical)
SELECT tpl.chamber_id, pd.id, 'Board Member (At-Large)', tpl.representing_state, tpl.representing_city, 1,
       tpl.normalized_position_name, tpl.partisan_type, false, false, tpl.role_canonical
  FROM _hold h
  JOIN essentials.districts pd ON pd.geo_id = h.parent_geo AND pd.district_type = 'SCHOOL' AND pd.mtfcc = 'G5420'
  CROSS JOIN LATERAL (SELECT o.* FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
                       WHERE d.district_type = 'SCHOOL'
                         AND (d.geo_id IN (SELECT s2.geo_id FROM _seat s2 WHERE s2.parent_geo = h.parent_geo)
                              OR (d.geo_id = h.parent_geo AND d.mtfcc = 'G5420'))
                       ORDER BY o.id LIMIT 1) tpl
 WHERE (SELECT count(*) FROM essentials.offices o WHERE o.district_id = pd.id) < h.ord;

-- ─── 3c. SURPLUS seats (more offices than the board has seats): delete ────────────────────
-- (decision 2026-09-22: a seat that does not exist is deleted; its stale term cascades. Never
-- when a race references it -- the pre-flight above refuses that case.)
DELETE FROM essentials.offices o
 USING (SELECT o2.id, pd.geo_id, row_number() OVER (PARTITION BY pd.geo_id ORDER BY o2.id) AS rk
          FROM essentials.offices o2 JOIN essentials.districts pd ON pd.id = o2.district_id
         WHERE pd.district_type = 'SCHOOL' AND pd.mtfcc = 'G5420' AND pd.geo_id IN (SELECT DISTINCT parent_geo FROM _seat)) x
 WHERE o.id = x.id AND x.rk > (SELECT count(*) FROM _hold h WHERE h.parent_geo = x.geo_id)
   AND NOT EXISTS (SELECT 1 FROM essentials.races r WHERE r.office_id = o.id);
-- The kept parent offices are the district-wide (at-large) seats of the holdovers.
UPDATE essentials.offices o SET title = 'Board Member (At-Large)'
  FROM essentials.districts pd
 WHERE o.district_id = pd.id AND pd.district_type = 'SCHOOL' AND pd.mtfcc = 'G5420'
   AND pd.geo_id IN (SELECT DISTINCT parent_geo FROM _hold) AND o.title IS DISTINCT FROM 'Board Member (At-Large)';

-- ─── 4. Politician rows for the sitting members (party NULL: never stored) ────────────────
INSERT INTO essentials.politicians (first_name, last_name, full_name, party, party_short_name,
                                    is_active, is_incumbent, is_vacant, is_appointed, data_source)
SELECT s.first_name, s.last_name, s.full_name, NULL, NULL, true, true, false, false, s.url
  FROM _seat s
 WHERE s.existing_pid IS NULL AND s.full_name IS NOT NULL AND s.vacant_since IS NULL AND s.first_name IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM essentials.politicians p WHERE p.full_name = s.full_name AND p.data_source = s.url);

INSERT INTO essentials.politicians (first_name, last_name, full_name, party, party_short_name,
                                    is_active, is_incumbent, is_vacant, is_appointed, data_source)
SELECT h.first_name, h.last_name, h.full_name, NULL, NULL, true, true, false, false, h.url
  FROM _hold h
 WHERE h.existing_pid IS NULL
   AND NOT EXISTS (SELECT 1 FROM essentials.politicians p WHERE p.full_name = h.full_name AND p.data_source = h.url);
UPDATE _hold h SET pid = COALESCE(h.existing_pid,
  (SELECT p.id FROM essentials.politicians p WHERE p.full_name = h.full_name AND p.data_source = h.url ORDER BY p.created_at LIMIT 1));

UPDATE _seat s SET pid = COALESCE(s.existing_pid,
  (SELECT p.id FROM essentials.politicians p WHERE p.full_name = s.full_name AND p.data_source = s.url ORDER BY p.created_at LIMIT 1));


-- ─── 5. Close each stale term the day before its successor starts ─────────────────────────
-- Convention agreed 2026-09-22 (both LA roster sessions): how_ended 'unknown', end date not researched.
UPDATE essentials.office_terms t
   SET term_end = s.term_start - 1,
       how_ended = 'unknown',
       source = COALESCE(t.source, '') || ' | CA_0152: closed as stale; the district''s current board page does not list this person; end date NOT researched (set to the day before the verified successor''s term start)'
  FROM _seat s
  JOIN essentials.districts sd ON sd.geo_id = s.geo_id AND sd.district_type = 'SCHOOL'
  JOIN essentials.offices o ON o.district_id = sd.id
 WHERE t.office_id = o.id AND t.term_end IS NULL AND t.politician_id IS DISTINCT FROM s.pid;

UPDATE essentials.politicians p
   SET is_incumbent = false
 WHERE p.is_incumbent
   AND p.id IN (SELECT t.politician_id FROM essentials.office_terms t
                  JOIN essentials.offices o ON o.id = t.office_id
                  JOIN essentials.districts sd ON sd.id = o.district_id
                  JOIN _seat s ON s.geo_id = sd.geo_id
                 WHERE t.how_ended = 'unknown' AND t.term_end = s.term_start - 1)
   AND NOT EXISTS (SELECT 1 FROM essentials.current_office_holders coh WHERE coh.politician_id = p.id);

-- ─── 5b. At-large holdovers: close the stale term on each kept parent office, seat the holdover ─
CREATE TEMP TABLE _hold_office ON COMMIT DROP AS
SELECT h.*, x.id AS office_id
  FROM _hold h
  JOIN (SELECT o.id, pd.geo_id, row_number() OVER (PARTITION BY pd.geo_id ORDER BY o.id) AS rk
          FROM essentials.offices o JOIN essentials.districts pd ON pd.id = o.district_id
         WHERE pd.district_type = 'SCHOOL' AND pd.mtfcc = 'G5420') x ON x.geo_id = h.parent_geo AND x.rk = h.ord;
UPDATE essentials.office_terms t
   SET term_end = ho.term_start - 1, how_ended = 'unknown',
       source = COALESCE(t.source, '') || ' | CA_0152: closed as stale; the district''s current board page does not list this person; end date NOT researched (set to the day before the verified successor''s term start)'
  FROM _hold_office ho
 WHERE t.office_id = ho.office_id AND t.term_end IS NULL AND t.politician_id IS DISTINCT FROM ho.pid;
UPDATE essentials.politicians p SET is_incumbent = false
 WHERE p.is_incumbent
   AND p.id IN (SELECT t.politician_id FROM essentials.office_terms t JOIN _hold_office ho ON ho.office_id = t.office_id
                 WHERE t.how_ended = 'unknown' AND t.term_end = ho.term_start - 1)
   AND NOT EXISTS (SELECT 1 FROM essentials.current_office_holders coh WHERE coh.politician_id = p.id);
INSERT INTO essentials.office_terms (office_id, politician_id, term_start, start_precision, how_started, source)
SELECT ho.office_id, ho.pid, ho.term_start, ho.prec, ho.how, ho.src FROM _hold_office ho
 WHERE ho.pid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM essentials.office_terms t WHERE t.office_id = ho.office_id AND t.politician_id = ho.pid);
UPDATE essentials.politicians p SET is_incumbent = true, party = NULL, party_short_name = NULL
  FROM _hold h WHERE p.id = h.pid AND (NOT p.is_incumbent OR p.party IS NOT NULL OR p.party_short_name IS NOT NULL);

-- ─── 6. Seat the current members ──────────────────────────────────────────────────────────
INSERT INTO essentials.office_terms (office_id, politician_id, term_start, start_precision, how_started, source)
SELECT o.id, s.pid, s.term_start, s.prec, s.how, s.src
  FROM _seat s
  JOIN essentials.districts sd ON sd.geo_id = s.geo_id AND sd.district_type = 'SCHOOL'
  JOIN essentials.offices o ON o.district_id = sd.id
 WHERE s.pid IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM essentials.office_terms t WHERE t.office_id = o.id AND t.politician_id = s.pid);

UPDATE essentials.politicians p SET is_incumbent = true FROM _seat s WHERE p.id = s.pid AND NOT p.is_incumbent;
-- Party is never stored: clear it on every seated member (reused rows can carry a legacy 'Nonpartisan').
UPDATE essentials.politicians p SET party = NULL, party_short_name = NULL FROM _seat s WHERE p.id = s.pid AND (p.party IS NOT NULL OR p.party_short_name IS NOT NULL);
-- A verified VACANT area: flag the seat (the span is written only where its start is known).
UPDATE essentials.offices o SET is_vacant = true, vacant_since = s.vacant_since
  FROM _seat s JOIN essentials.districts sd ON sd.geo_id = s.geo_id AND sd.district_type = 'SCHOOL'
 WHERE o.district_id = sd.id AND s.full_name IS NULL AND NOT o.is_vacant;

-- ─── 7. Nov 3 2026 trustee-area races (nonpartisan: primary_party NULL) ───────────────────
INSERT INTO essentials.races (election_id, office_id, position_name, primary_party, seats)
SELECT 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid, o.id, v.position_name, NULL, 1
  FROM (VALUES
    ('0629850-ta-1', 'Paramount Unified School Board - Trustee Area 1'),
    ('0629850-ta-4', 'Paramount Unified School Board - Trustee Area 4'),
    ('0629850-ta-5', 'Paramount Unified School Board - Trustee Area 5'),
    ('0625470-ta-1', 'Montebello Unified School Board - Trustee Area 1'),
    ('0625470-ta-2', 'Montebello Unified School Board - Trustee Area 2'),
    ('0625470-ta-3', 'Montebello Unified School Board - Trustee Area 3'),
    ('0600001-ta-1', 'Acton-Agua Dulce Unified School Board - Trustee Area 1'),
    ('0600001-ta-2', 'Acton-Agua Dulce Unified School Board - Trustee Area 2'),
    ('0600001-ta-4', 'Acton-Agua Dulce Unified School Board - Trustee Area 4')
  ) AS v(geo_id, position_name)
  JOIN essentials.districts sd ON sd.geo_id = v.geo_id AND sd.district_type = 'SCHOOL'
  JOIN essentials.offices o ON o.district_id = sd.id
 WHERE NOT EXISTS (SELECT 1 FROM essentials.races r WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = v.position_name);

INSERT INTO essentials.race_candidates
       (race_id, politician_id, full_name, first_name, last_name, is_incumbent, candidate_status, source)
SELECT r.id, COALESCE((SELECT s.pid FROM _seat s WHERE s.geo_id = v.geo_id AND s.full_name = v.seat_name),
                      (SELECT h.pid FROM _hold h JOIN _seat s3 ON s3.parent_geo = h.parent_geo AND s3.geo_id = v.geo_id
                        WHERE h.full_name = v.seat_name LIMIT 1),
                      (SELECT s4.pid FROM _seat s4 JOIN _seat s5 ON s5.parent_geo = s4.parent_geo AND s5.geo_id = v.geo_id
                        WHERE s4.full_name = v.seat_name LIMIT 1)),
       v.full_name, v.first_name, v.last_name, v.is_incumbent, 'active',
       'LA County Registrar-Recorder, Nov 3 2026 General Election certified candidate list (lavote.gov/Apps/CandidateList/Index?id=4348). Retrieved 2026-09-22.'
  FROM (VALUES
    ('Paramount Unified School Board - Trustee Area 1', '0629850-ta-1', 'Sonia Olmos', 'Sonia', 'Olmos', true, 'Sonia Olmos'),
    ('Paramount Unified School Board - Trustee Area 4', '0629850-ta-4', 'Alicia Linden Anderson', 'Alicia', 'Anderson', true, 'Alicia Anderson'),
    ('Paramount Unified School Board - Trustee Area 4', '0629850-ta-4', 'Yesenia Maria Cuarenta', 'Yesenia', 'Cuarenta', true, 'Yesenia Cuarenta'),
    ('Paramount Unified School Board - Trustee Area 5', '0629850-ta-5', 'Tricia Bass-Riedel', 'Tricia', 'Bass-Riedel', false, NULL),
    ('Montebello Unified School Board - Trustee Area 1', '0625470-ta-1', 'Carlos Cerdan', 'Carlos', 'Cerdan', true, 'Carlos Cerdan'),
    ('Montebello Unified School Board - Trustee Area 2', '0625470-ta-2', 'Jasmin Jauregui Paulson', 'Jasmin', 'Paulson', false, NULL),
    ('Montebello Unified School Board - Trustee Area 2', '0625470-ta-2', 'Lizbeth Renova', 'Lizbeth', 'Renova', false, NULL),
    ('Montebello Unified School Board - Trustee Area 2', '0625470-ta-2', 'Aaron Reveles', 'Aaron', 'Reveles', false, NULL),
    ('Montebello Unified School Board - Trustee Area 3', '0625470-ta-3', 'Jennifer Gutierrez', 'Jennifer', 'Gutierrez', true, 'Jennifer Gutierrez'),
    ('Acton-Agua Dulce Unified School Board - Trustee Area 1', '0600001-ta-1', 'Ken Pfalzgraf', 'Ken', 'Pfalzgraf', true, 'Ken Pfalzgraf'),
    ('Acton-Agua Dulce Unified School Board - Trustee Area 2', '0600001-ta-2', 'Geraldine Rose Davis-Duzick', 'Geraldine', 'Davis-Duzick', false, NULL),
    ('Acton-Agua Dulce Unified School Board - Trustee Area 4', '0600001-ta-4', 'Jessica Gonyea', 'Jessica', 'Gonyea', true, 'Jessica Gonyea'),
    ('Acton-Agua Dulce Unified School Board - Trustee Area 4', '0600001-ta-4', 'Michael E. Hammett', 'Michael', 'Hammett', false, NULL)
  ) AS v(position_name, geo_id, full_name, first_name, last_name, is_incumbent, seat_name)
  JOIN essentials.races r ON r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = v.position_name
 WHERE NOT EXISTS (SELECT 1 FROM essentials.race_candidates rc WHERE rc.race_id = r.id AND lower(rc.full_name) = lower(v.full_name));

-- ─── 8. Post-verify gate ──────────────────────────────────────────────────────────────────
DO $$
DECLARE n int; n2 int; worst double precision;
BEGIN
  SELECT count(*) INTO n FROM _seat s JOIN essentials.geofence_boundaries gb ON gb.geo_id = s.geo_id AND gb.mtfcc = 'X0002'
   WHERE public.ST_IsValid(gb.geometry);
  IF n <> 11 THEN RAISE EXCEPTION 'expected 11 valid trustee-area polygons, got %', n; END IF;

  -- each area: exactly one office, and it is held by exactly the member named for that area
  SELECT count(*) INTO n FROM _seat s JOIN essentials.districts sd ON sd.geo_id = s.geo_id AND sd.district_type = 'SCHOOL' AND sd.mtfcc = 'X0002'
   WHERE (SELECT count(*) FROM essentials.offices o WHERE o.district_id = sd.id) = 1
     AND (SELECT och.politician_id FROM essentials.office_current_holder och JOIN essentials.offices o ON o.id = och.office_id
           WHERE o.district_id = sd.id) IS NOT DISTINCT FROM s.pid
     AND (s.full_name IS NOT NULL OR (SELECT bool_and(o.is_vacant) FROM essentials.offices o WHERE o.district_id = sd.id));
  IF n <> 11 THEN RAISE EXCEPTION 'expected 11 areas each held by its named member, got %', n; END IF;

  -- whole-district rows keep exactly one office per at-large holdover, each held by that holdover
  SELECT count(*) INTO n FROM essentials.offices o JOIN essentials.districts pd ON pd.id = o.district_id
   WHERE pd.district_type = 'SCHOOL' AND pd.mtfcc = 'G5420' AND pd.geo_id IN ('0629850', '0625470', '0600001');
  IF n <> 12 THEN RAISE EXCEPTION 'expected 12 at-large office(s) on the whole-district rows, got %', n; END IF;
  SELECT count(*) INTO n FROM _hold h
   WHERE NOT EXISTS (SELECT 1 FROM essentials.office_current_holder och JOIN essentials.offices o ON o.id = och.office_id
                       JOIN essentials.districts pd ON pd.id = o.district_id
                      WHERE pd.geo_id = h.parent_geo AND pd.mtfcc = 'G5420' AND och.politician_id = h.pid);
  IF n <> 0 THEN RAISE EXCEPTION '% at-large holdover(s) not seated on their district-wide office', n; END IF;

  SELECT count(*) INTO n FROM _seat s JOIN essentials.districts sd ON sd.geo_id = s.geo_id AND sd.district_type = 'SCHOOL'
    JOIN essentials.offices o ON o.district_id = sd.id JOIN essentials.office_terms t ON t.office_id = o.id
   WHERE t.term_end IS NULL AND t.politician_id IS DISTINCT FROM s.pid;
  IF n <> 0 THEN RAISE EXCEPTION '% stale open term(s) remain', n; END IF;

  SELECT count(*) INTO n FROM _seat s JOIN essentials.politicians p ON p.id = s.pid WHERE p.party IS NOT NULL AND s.existing_pid IS NULL;
  IF n <> 0 THEN RAISE EXCEPTION '% new member row(s) carry a party', n; END IF;

  -- coverage per district vs its TIGER reference: the unified polygon, plus any extra TIGER polygon the
  -- board also covers (e.g. a 9-12-only area). Planar ratio; no ::geography (decision 0006).
  -- (a) the trustee areas must lie inside the TIGER polygon (<= 1 pct outside);
  -- (b) they must cover it to within the district's tolerance (default 3 pct; a coastal TIGER polygon
  --     that includes open water gets a larger, documented tolerance).
  SELECT max(public.ST_Area(public.ST_Difference(u.g, t.geometry)) / public.ST_Area(u.g)) INTO worst
    FROM (SELECT s.parent_geo, public.ST_Union(gb.geometry) g FROM _seat s
            JOIN essentials.geofence_boundaries gb ON gb.geo_id = s.geo_id AND gb.mtfcc = 'X0002' GROUP BY 1) u
    JOIN (SELECT ref.parent_geo, public.ST_Union(rg.geometry) AS geometry
            FROM (VALUES ('0629850', '0629850', 'G5420'), ('0625470', '0625470', 'G5420'), ('0600001', '0600001', 'G5420')) AS ref(parent_geo, geo_id, mtfcc)
            JOIN essentials.geofence_boundaries rg ON rg.geo_id = ref.geo_id AND rg.mtfcc = ref.mtfcc
           GROUP BY ref.parent_geo) t ON t.parent_geo = u.parent_geo;
  IF worst > 0.01 THEN RAISE EXCEPTION 'trustee areas extend % pct outside their TIGER polygon', round((worst*100)::numeric, 2); END IF;
  SELECT count(*) INTO n
    FROM (SELECT s.parent_geo, public.ST_Union(gb.geometry) g FROM _seat s
            JOIN essentials.geofence_boundaries gb ON gb.geo_id = s.geo_id AND gb.mtfcc = 'X0002' GROUP BY 1) u
    JOIN (SELECT ref.parent_geo, public.ST_Union(rg.geometry) AS geometry
            FROM (VALUES ('0629850', '0629850', 'G5420'), ('0625470', '0625470', 'G5420'), ('0600001', '0600001', 'G5420')) AS ref(parent_geo, geo_id, mtfcc)
            JOIN essentials.geofence_boundaries rg ON rg.geo_id = ref.geo_id AND rg.mtfcc = ref.mtfcc
           GROUP BY ref.parent_geo) t ON t.parent_geo = u.parent_geo
    LEFT JOIN (VALUES ('0629850', 0.03::float8), ('0625470', 1.0::float8), ('0600001', 1.0::float8)) AS tol(parent_geo, tol) ON tol.parent_geo = u.parent_geo
   WHERE abs(public.ST_Area(t.geometry) - public.ST_Area(u.g)) / public.ST_Area(t.geometry) > COALESCE(tol.tol, 0.03);
  IF n <> 0 THEN RAISE EXCEPTION '% district(s) whose trustee areas do not cover their TIGER polygon within tolerance', n; END IF;
  SELECT max(abs(public.ST_Area(t.geometry) - public.ST_Area(u.g)) / public.ST_Area(t.geometry)) INTO worst
    FROM (SELECT s.parent_geo, public.ST_Union(gb.geometry) g FROM _seat s
            JOIN essentials.geofence_boundaries gb ON gb.geo_id = s.geo_id AND gb.mtfcc = 'X0002' GROUP BY 1) u
    JOIN (SELECT ref.parent_geo, public.ST_Union(rg.geometry) AS geometry
            FROM (VALUES ('0629850', '0629850', 'G5420'), ('0625470', '0625470', 'G5420'), ('0600001', '0600001', 'G5420')) AS ref(parent_geo, geo_id, mtfcc)
            JOIN essentials.geofence_boundaries rg ON rg.geo_id = ref.geo_id AND rg.mtfcc = ref.mtfcc
           GROUP BY ref.parent_geo) t ON t.parent_geo = u.parent_geo;

  -- partition: no two areas of one district overlap beyond ~1,000 m2 (1e-7 deg2 at 34 N)
  SELECT count(*) INTO n FROM _seat a JOIN _seat b ON a.parent_geo = b.parent_geo AND a.geo_id < b.geo_id
    JOIN essentials.geofence_boundaries ga ON ga.geo_id = a.geo_id AND ga.mtfcc = 'X0002'
    JOIN essentials.geofence_boundaries gb ON gb.geo_id = b.geo_id AND gb.mtfcc = 'X0002'
   WHERE public.ST_Area(public.ST_Intersection(ga.geometry, gb.geometry)) > 1e-7;
  IF n <> 0 THEN RAISE EXCEPTION '% trustee-area pair(s) overlap', n; END IF;

  -- END TO END: an interior point of each area returns exactly its own member among that district's seats
  SELECT count(*) INTO n FROM _seat me JOIN essentials.geofence_boundaries mg ON mg.geo_id = me.geo_id AND mg.mtfcc = 'X0002'
   WHERE me.full_name IS NOT NULL AND (SELECT string_agg(och.politician_id::text, ',') FROM _seat s2
            JOIN essentials.geofence_boundaries gb ON gb.geo_id = s2.geo_id AND gb.mtfcc = 'X0002'
            JOIN essentials.districts d ON d.geo_id = gb.geo_id AND d.district_type = 'SCHOOL' AND d.mtfcc = 'X0002'
            JOIN essentials.offices o ON o.district_id = d.id
            JOIN essentials.office_current_holder och ON och.office_id = o.id AND och.politician_id IS NOT NULL
           WHERE s2.parent_geo = me.parent_geo AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(mg.geometry)))
         IS DISTINCT FROM me.pid::text;
  IF n <> 0 THEN RAISE EXCEPTION '% trustee area(s) do not return exactly their own member at an interior point', n; END IF;

  SELECT count(*) INTO n FROM essentials.races r JOIN essentials.offices o ON o.id = r.office_id
    JOIN essentials.districts d ON d.id = o.district_id JOIN _seat s ON s.geo_id = d.geo_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.primary_party IS NULL;
  SELECT count(*) INTO n2 FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id JOIN _seat s ON s.geo_id = d.geo_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid;
  IF n <> 9 OR n2 <> 13 THEN RAISE EXCEPTION 'expected 9 races / 13 candidates, got % / %', n, n2; END IF;

  -- every incumbent candidate is linked to the member seated on that area
  SELECT count(*) INTO n FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id JOIN _seat s ON s.geo_id = d.geo_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND rc.is_incumbent AND rc.politician_id IS DISTINCT FROM s.pid
     AND NOT EXISTS (SELECT 1 FROM _hold h WHERE h.parent_geo = s.parent_geo AND h.pid = rc.politician_id)
     AND NOT EXISTS (SELECT 1 FROM _seat s6 WHERE s6.parent_geo = s.parent_geo AND s6.pid = rc.politician_id);
  IF n <> 0 THEN RAISE EXCEPTION '% incumbent candidate(s) not linked to the seated member', n; END IF;

  RAISE NOTICE 'CA_0152 applied: 11 trustee areas, 9 races, 13 candidates';
END $$;

COMMIT;
